import{_ as a,o,c as r,ag as t}from"./chunks/framework.ePeAWSvT.js";const _=JSON.parse('{"title":"从零实现 MLP：当 nn.Linear 不再替你隐藏细节","description":"手动实现参数、ReLU、稳定交叉熵与 SGD，并用验证集完成公平比较。","frontmatter":{"title":"从零实现 MLP：当 nn.Linear 不再替你隐藏细节","description":"手动实现参数、ReLU、稳定交叉熵与 SGD，并用验证集完成公平比较。"},"headers":[],"relativePath":"posts/mlp-from-scratch.md","filePath":"posts/mlp-from-scratch.md","lastUpdated":1786688709000}'),n={name:"posts/mlp-from-scratch.md"};function c(i,e,p,d,l,s){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="从零实现-mlp-当-nn-linear-不再替你隐藏细节" tabindex="-1">从零实现 MLP：当 <code>nn.Linear</code> 不再替你隐藏细节 <a class="header-anchor" href="#从零实现-mlp-当-nn-linear-不再替你隐藏细节" aria-label="Permalink to &quot;从零实现 MLP：当 `nn.Linear` 不再替你隐藏细节&quot;">​</a></h1><blockquote><p>项目代码：<a href="https://github.com/isLLccu/deep-learning-foundations/tree/main/projects/01-mlp-from-scratch" target="_blank" rel="noreferrer">deep-learning-foundations</a></p></blockquote><p>调用 <code>nn.Linear</code> 写出一个 MLP 很容易，但如果把它拿掉，我们是否真的知道模型内部发生了什么？这个实验从张量开始，实现一个 <code>784 → 128 → 10</code> 的 Fashion-MNIST 分类器。</p><h2 id="_1-我手动实现了什么" tabindex="-1">1. 我手动实现了什么 <a class="header-anchor" href="#_1-我手动实现了什么" aria-label="Permalink to &quot;1. 我手动实现了什么&quot;">​</a></h2><p>模型只有一个隐藏层：</p><p>$$ H = \\operatorname{ReLU}(XW_1+b_1), \\qquad O = HW_2+b_2. $$</p><p>手写版本没有使用 <code>nn.Linear</code>，而是显式创建四组可训练张量：<code>W1</code>、<code>b1</code>、<code>W2</code>、<code>b2</code>。前向传播使用矩阵乘法，ReLU 使用逐元素最大值。</p><p>交叉熵也不先计算 softmax，而是使用稳定形式：</p><p>$$ \\log p_y = o_y - \\operatorname{logsumexp}(O). $$</p><p>这样避免指数值过大造成数值溢出。反向传播仍使用 PyTorch autograd，但 SGD 更新由我在 <code>torch.no_grad()</code> 中手动完成。</p><h2 id="_2-怎样保证比较公平" tabindex="-1">2. 怎样保证比较公平 <a class="header-anchor" href="#_2-怎样保证比较公平" aria-label="Permalink to &quot;2. 怎样保证比较公平&quot;">​</a></h2><p>我又实现了等价的 <code>nn.Module + nn.Linear</code> 版本。两者比较时固定：</p><ul><li>完全相同的初始权重和偏置；</li><li>完全相同的 mini-batch 顺序；</li><li>相同的网络结构、学习率、批量大小和 epoch 数；</li><li>相同的 55,000 / 5,000 训练—验证划分。</li></ul><p>两种实现的参数量都为：</p><p>$$ 784\\times128 + 128 + 128\\times10 + 10 = 101{,}770. $$</p><h2 id="_3-我修正的实验问题" tabindex="-1">3. 我修正的实验问题 <a class="header-anchor" href="#_3-我修正的实验问题" aria-label="Permalink to &quot;3. 我修正的实验问题&quot;">​</a></h2><p>原始版本每个 epoch 都查看测试准确率，并据此选择学习率。这会让测试集参与决策，最终数字不再是独立估计。</p><p>精修版本把 Fashion-MNIST 的 60,000 张训练图片拆为 55,000 张训练数据和 5,000 张验证数据。学习率与 batch size 只根据验证曲线选择；官方测试集只在两个模型训练完成后评估一次。</p><p>这次修正比提高零点几个百分点更重要，因为它决定了实验结论是否可信。</p><h2 id="_4-结论" tabindex="-1">4. 结论 <a class="header-anchor" href="#_4-结论" aria-label="Permalink to &quot;4. 结论&quot;">​</a></h2><p>两个模型的曲线非常接近，说明手写的矩阵运算、激活、损失和 SGD 与 PyTorch 封装具有相同数学含义。<code>nn.Module</code> 的优势是代码更简洁、工程接口更完整；手写版本的价值是把抽象层下面的机制变成可以检查的对象。</p><p>这个 MLP 没有利用图像的空间结构，因此它不是追求最高精度的方案。它是一块干净的“机制验证板”。</p>',22)])])}const m=a(n,[["render",c]]);export{_ as __pageData,m as default};
